function getMoves(b,r,c,ep=enPassantTarget,rights=castlingRights){const p=b[r][c];if(!p)return[];const s=side(p),t=type(p),out=[];const add=(rr,cc)=>{if(inside(rr,cc)&&side(b[rr][cc])!==s&&type(b[rr][cc])!=='k')out.push({r:rr,c:cc})};const addPawn=(rr,cc,extra={})=>{if(rr===0||rr===7)for(const promotion of ['q','r','b','n'])out.push({r:rr,c:cc,promotion,...extra});else out.push({r:rr,c:cc,...extra})};if(t==='p'){const d=s==='w'?-1:1,start=s==='w'?6:1;if(inside(r+d,c)&&!b[r+d][c]){addPawn(r+d,c);if(r===start&&!b[r+2*d][c])out.push({r:r+2*d,c})}for(const dc of [-1,1]){const rr=r+d,cc=c+dc;if(!inside(rr,cc))continue;if(side(b[rr][cc])&&side(b[rr][cc])!==s&&type(b[rr][cc])!=='k')addPawn(rr,cc);else if(ep&&ep[0]===rr&&ep[1]===cc)addPawn(rr,cc,{enPassant:true})}}else if(t==='n'){for(const[dr,dc]of [[-2,-1],[-2,1],[-1,-2],[-1,2],[1,-2],[1,2],[2,-1],[2,1]])add(r+dr,c+dc)}else if(t==='k'){for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++)if(dr||dc)add(r+dr,c+dc);const home=s==='w'?7:0;if(r===home&&c===4&&!inCheck(b,s)){if(rights?.[s]?.k&&!b[home][5]&&!b[home][6]&&b[home][7]===s+'r'&&!isSquareAttacked(b,home,5,s==='w'?'b':'w')&&!isSquareAttacked(b,home,6,s==='w'?'b':'w'))out.push({r:home,c:6,castle:'k'});if(rights?.[s]?.q&&!b[home][1]&&!b[home][2]&&!b[home][3]&&b[home][0]===s+'r'&&!isSquareAttacked(b,home,3,s==='w'?'b':'w')&&!isSquareAttacked(b,home,2,s==='w'?'b':'w'))out.push({r:home,c:2,castle:'q'})}}else{const dirs=[];if(t==='r'||t==='q')dirs.push([1,0],[-1,0],[0,1],[0,-1]);if(t==='b'||t==='q')dirs.push([1,1],[1,-1],[-1,1],[-1,-1]);for(const[dr,dc]of dirs){let rr=r+dr,cc=c+dc;while(inside(rr,cc)){if(!b[rr][cc])out.push({r:rr,c:cc});else{if(side(b[rr][cc])!==s&&type(b[rr][cc])!=='k')out.push({r:rr,c:cc});break}rr+=dr;cc+=dc}}}return out}
