function boardToFen(position,active='w',rights=castlingRights,ep=enPassantTarget,halfmove=0,fullmove=1){const rows=position.map(row=>{let line='',empty=0;for(const piece of row){if(!piece){empty++;continue}if(empty){line+=empty;empty=0}const letter=type(piece);line+=side(piece)==='w'?letter.toUpperCase():letter}if(empty)line+=empty;return line});const castling=`${rights?.w?.k?'K':''}${rights?.w?.q?'Q':''}${rights?.b?.k?'k':''}${rights?.b?.q?'q':''}`||'-',epSquare=ep?`${'abcdefgh'[ep[1]]}${8-ep[0]}`:'-';return`${rows.join('/')} ${active} ${castling} ${epSquare} ${halfmove||0} ${fullmove||1}`}
