function evaluate(b,perspective='b'){let score=0;for(let r=0;r<8;r++)for(let c=0;c<8;c++){const p=b[r][c];if(p)score+=(side(p)===perspective?1:-1)*values[type(p)]}return score}
function search(b,s,depth,alpha,beta,ep=enPassantTarget,rights=castlingRights,perspective='b'){const moves=allLegal(s,b,ep,rights);if(!depth||!moves.length)return {score:moves.length?evaluate(b,perspective):(inCheck(b,s)?(s===perspective?-100000:100000):0)};const maximizing=s===perspective;let best=maximizing?-Infinity:Infinity;for(const move of moves){const next=applyMove(b,move,ep,rights);const score=search(next.board,otherSide(s),depth-1,alpha,beta,next.ep,next.rights,perspective).score;if(maximizing){best=Math.max(best,score);alpha=Math.max(alpha,best)}else{best=Math.min(best,score);beta=Math.min(beta,best)}if(beta<=alpha)break}return {score:best}}
function chooseBotMove(){const botSide=otherSide(humanSide),moves=allLegal(botSide);if(!moves.length)return null;let best=-Infinity,bestMoves=[];for(const move of moves){const next=applyMove(board,move,enPassantTarget,castlingRights);const score=search(next.board,humanSide,2,-Infinity,Infinity,next.ep,next.rights,botSide).score;if(score>best){best=score;bestMoves=[move]}else if(score===best)bestMoves.push(move)}return bestMoves[Math.floor(Math.random()*bestMoves.length)]||moves[0]}
function useVillainPowerImplementation(){const botSide=otherSide(humanSide),human=humanSide;if(mode!=='tournament'||inCheck(board,botSide))return 'none';const power=tournamentOpponents[tournamentRound].power,last=history[history.length-1];if(tournamentOpponents[tournamentRound].portrait==='valentine'&&!loveTrainUsed){queueReviewPower('lovetrain',botSide,'Love Train: proteção ativada por dois turnos.');loveTrainUsed=true;loveTrainOwner=botSide;loveTrainRemaining=2;showPowerEffect('lovetrain',botSide);recordImmediateReviewPower();return 'continue'}if(power==='crimson'&&(usedPower[botSide].crimson||0)===0&&last?.piece[0]===human&&last.captured&&['q','r'].includes(type(last.captured))){usedPower[botSide].crimson=3;queueReviewPower('crimson',botSide,'Apagar o Tempo: desfez o último lance adversário.');showPowerEffect('crimson',botSide);undoLastMove();recordImmediateReviewPower();return 'replay'}if(power==='arrow'&&(usedPower[botSide].arrow||0)===0){for(let r=0;r<8;r++)for(let c=0;c<8;c++)if(board[r][c]===botSide+'p'){queueReviewPower('arrow',botSide,`Flecha do Stand: promoveu o peão em ${squareName([r,c])} a dama.`,[r,c],[r,c]);board[r][c]=botSide+'q';showPowerEffect('arrow',botSide);usedPower[botSide].arrow=3;halfmoveClock=0;completeAction();return 'spent'}}if(power==='diamond'&&(usedPower[botSide].diamond||0)===0){const stash=captured[human];let restoreIndex=-1;for(let i=stash.length-1;i>=0;i--)if(side(stash[i])===botSide&&type(stash[i])!=='k'){restoreIndex=i;break}if(restoreIndex>=0){const piece=stash[restoreIndex];for(let r=0;r<8;r++)for(let c=0;c<8;c++)if(!board[r][c]){const next=board.map(row=>row.slice());next[r][c]=piece;if(!inCheck(next,botSide)){queueReviewPower('diamond',botSide,`Crazy Diamond: restaurou ${names[type(piece)]} em ${squareName([r,c])}.`,null,[r,c]);stash.splice(restoreIndex,1);board[r][c]=piece;showPowerEffect('diamond',botSide);usedPower[botSide].diamond=3;completeAction();return 'spent'}}}}if(power==='killer'&&(usedPower[botSide].killer||0)===0){const targets=[];for(let r=0;r<8;r++)for(let c=0;c<8;c++)if(side(board[r][c])===human&&type(board[r][c])!=='k'){const next=board.map(row=>row.slice());next[r][c]=null;if(!inCheck(next,botSide))targets.push({r,c,piece:board[r][c]})}targets.sort((a,b)=>values[type(b.piece)]-values[type(a.piece)]);if(targets.length){const target=targets[0];queueReviewPower('killer',botSide,`Killer Queen: explodiu ${names[type(target.piece)]} em ${squareName([target.r,target.c])}.`,[target.r,target.c],[target.r,target.c]);captured[botSide].push(target.piece);board[target.r][target.c]=null;showPowerEffect('killer',botSide);usedPower[botSide].killer=3;halfmoveClock=0;completeAction();return 'spent'}}if(power==='hamon'&&(usedPower[botSide].hamon||0)===0){const pawnSquares=[];for(let r=0;r<8;r++)for(let c=0;c<8;c++)if(board[r][c]===human+'p'&&(botSide==='b'?r<=3:r>=4)){const next=board.map(row=>row.slice());next[r][c]=null;if(!inCheck(next,botSide))pawnSquares.push([r,c])}if(pawnSquares.length){pawnSquares.sort((a,b)=>botSide==='b'?a[0]-b[0]:b[0]-a[0]);const [r,c]=pawnSquares[0];queueReviewPower('hamon',botSide,`Onda Hamon: removeu um peão em ${squareName([r,c])}.`,[r,c],[r,c]);captured[botSide].push(board[r][c]);board[r][c]=null;showPowerEffect('hamon',botSide);usedPower[botSide].hamon=3;halfmoveClock=0;completeAction();return 'spent'}}if(power==='time'&&(usedPower[botSide].time||0)===0){queueReviewPower('time',botSide,'Parada do Tempo: ganhou um lance extra.');showPowerEffect('time',botSide);usedPower[botSide].time=3;extraTurn=true;recordImmediateReviewPower();return 'continue'}return 'none'}
function useVillainPower(){if(!isTournamentOpponentPowered())return 'none';return useVillainPowerImplementation()}
function scheduleBot(){const botSide=otherSide(humanSide),token=++botTurnToken;botThinking=true;statusEl.textContent=`${mode==='tournament'?tournamentOpponents[tournamentRound].name:'DIO'} está pensando...`;boardEl.classList.add('thinking');setTimeout(()=>{if(token!==botTurnToken||gameOver||!isSinglePlayerMode()||turn!==botSide){if(token===botTurnToken){botThinking=false;boardEl.classList.remove('thinking')}return}botThinking=false;boardEl.classList.remove('thinking');try{const powerAction=useVillainPower();if(powerAction==='spent')return;const move=chooseBotMove()||allLegal(botSide)[0];if(move){makeMove(move.from,move.to,move.promotion||'q');return}gameOver=true;statusEl.textContent='O bot não encontrou um lance legal. Reinicie a partida.';render()}catch(error){console.error('Falha ao calcular o lance do bot:',error);const fallback=allLegal(botSide)[0];if(fallback)makeMove(fallback.from,fallback.to,fallback.promotion||'q');else{gameOver=true;statusEl.textContent='O bot não encontrou um lance legal. Reinicie a partida.';render()}}},450)}
function updateStatus(){document.querySelector('#power-label').textContent=isTwoPlayerMode()?'PODER DE '+sideDisplayName(turn).toLocaleUpperCase():turn===humanSide?'PODER DE JOTARO':'PODER DO VILÃO';const activePower=isTwoPlayerMode()?localPowers[turn]:isSinglePlayerMode()&&turn===humanSide?equippedPower:null;if(loveTrainRemaining>0&&turn!==loveTrainOwner&&(activePower==='hamon'||activePower==='killer'))powerButton.disabled=true;if(gameOver)return;const check=inCheck(board,turn),opponent=sideDisplayName(isSinglePlayerMode()?otherSide(humanSide):otherSide(turn));statusEl.textContent=!canPlayTurn()?mode==='multiplayer'?(multiplayerGuestJoined?'Aguardando '+sideDisplayName(turn)+' jogar...':'Aguardando o segundo jogador entrar...'):opponent+' está pensando...':pendingPower==='hamon'?'Onda Hamon: escolha um peão inimigo no tabuleiro.':pendingPower==='killer'?'Killer Queen: escolha uma peça inimiga para explodir.':pendingPower==='arrow'?'Flecha do Stand: escolha um peão seu no tabuleiro.':pendingPower==='diamond'?'Crazy Diamond: escolha uma casa vazia para restaurar '+names[type(pendingRestorePiece)]+'.':(extraTurn?'TEMPO PARADO · ':'')+'A vez de '+sideDisplayName(turn)+(check?' · XEQUE':'');if(loveTrainRemaining>0&&turn!==loveTrainOwner)statusEl.textContent+=' · LOVE TRAIN: '+loveTrainRemaining+' turno(s) de proteção';statusEl.classList.toggle('check',check)}
function squareName([r,c]){return `${'abcdefgh'[c]}${8-r}`}
function renderLog(){moveList.replaceChildren();if(!history.length){const empty=document.createElement('li');empty.className='empty';empty.textContent='A aventura começa...';moveList.appendChild(empty);return}history.forEach((h,i)=>{const moveNumber=Math.floor(i/2)+1,li=document.createElement('li'),number=document.createElement('span'),player=document.createElement('strong'),detail=document.createElement('span');li.className=`move-entry move-${h.piece[0]==='w'?'white':'black'}`;number.className='move-number';number.textContent=h.piece[0]==='w'?`${moveNumber}.`:`${moveNumber}...`;player.className='move-player';player.textContent=sideDisplayName(h.piece[0]);detail.className='move-detail';detail.textContent=`${names[type(h.piece)]} ${squareName(h.from)} → ${squareName(h.to)}${h.captured?' × '+names[type(h.captured)]:''}`;li.append(number,player,detail);moveList.appendChild(li)});moveList.lastElementChild?.scrollIntoView({block:'nearest'})}
function renderCaptures(){const list=captured.w;if(!list.length){captureEl.className='capture-list empty';captureEl.textContent='Nenhuma peça capturada';return}captureEl.className='capture-list';captureEl.textContent=list.map(p=>glyph[p]).join(' ')}
function renderBracket(){const card=document.querySelector('#tournament-card'),list=document.querySelector('#bracket');card.hidden=mode!=='tournament';if(mode!=='tournament')return;list.innerHTML='';tournamentOpponents.forEach((opponent,index)=>{const item=document.createElement('li');item.className=index<tournamentRound?'done':index===tournamentRound?'current':'upcoming';item.textContent=`${index+1}. ${opponent.name}${index<tournamentRound?' · VENCIDO':index===tournamentRound?' · AGORA':''}${isTournamentOpponentPowered(index)?' · PODER DO RIVAL ATIVO':' · RIVAL SEM PODER'}${ownedPowers.includes(powerOrder[index])?' · PODER LIBERADO':''}`;list.appendChild(item)})}
function loadProfile(){try{const saved=JSON.parse(localStorage.getItem(accountStorageKey('profile'))||'{}');coins=Math.max(0,Number(saved.coins)||0);ownedPowers=Array.isArray(saved.unlockedPowers)?powerOrder.filter(power=>saved.unlockedPowers.includes(power)):[];equippedPower=ownedPowers.includes(saved.equippedPower)?saved.equippedPower:(ownedPowers[0]||null);profileCharacter=characterPhotos[saved.profileCharacter]?saved.profileCharacter:'jotaro'}catch{coins=0;ownedPowers=[];equippedPower=null;profileCharacter='jotaro'}if(isAdminAccount()){coins=ADMIN_COIN_BALANCE;ownedPowers=powerOrder.slice();equippedPower=powerOrder.includes(equippedPower)?equippedPower:powerOrder[0]}}
function saveProfile(){if(isAdminAccount()){coins=ADMIN_COIN_BALANCE;ownedPowers=powerOrder.slice();if(!powerOrder.includes(equippedPower))equippedPower=powerOrder[0]}const profile={coins,unlockedPowers:ownedPowers,equippedPower,profileCharacter,savedAt:Date.now()};try{localStorage.setItem(accountStorageKey('profile'),JSON.stringify(profile))}catch{}queueSave(accountDatabaseKey('profile'),profile);queueServerState({profile})}
function updateCoinDisplay(){const balance=isAdminAccount()?'∞':String(coins);document.querySelector('#coins-menu').textContent=balance;document.querySelector('#coins-game').textContent=balance;document.querySelector('#coins-shop').textContent=balance;document.querySelector('#menu-equipped').textContent=(powerInfo[equippedPower]?.title||'Nenhum poder');document.querySelector('#signed-in-as').textContent=currentUser?`Conta: ${currentUser.username}${isAdminAccount()?' · ADMIN':''}`:'';document.querySelector('#open-local-admin').hidden=currentUser?.role!=='admin';document.querySelector('#admin-code-input').disabled=!currentUser;document.querySelector('#activate-admin').disabled=!currentUser}
function renderShop(){
  const list=document.querySelector('#shop-items');
  list.replaceChildren();
  for(const [index,id] of powerOrder.entries()){
    const power=powerInfo[id],owned=ownedPowers.includes(id),equipped=equippedPower===id;
    const card=document.createElement('article');
    card.className=`shop-item${owned?' is-unlocked':''}${equipped?' is-equipped':''}`;
    const icon=document.createElement('span');icon.className='shop-item-icon';icon.innerHTML=powerIconSvg(id);icon.setAttribute('aria-hidden','true');
    const details=document.createElement('div');details.className='shop-item-details';
    const title=document.createElement('strong');title.className='shop-power-title';title.textContent=power.title;
    const character=document.createElement('span');character.className='shop-character';character.textContent=power.character;
    const description=document.createElement('p');description.className='shop-power-description';description.textContent=power.description;
    const recharge=document.createElement('span');recharge.className='shop-recharge';recharge.textContent='Recarga: 3 turnos';
    details.append(title,character,description,recharge);
    const controls=document.createElement('div');controls.className='shop-item-controls';
    const badge=document.createElement('span');badge.className=`shop-state${equipped?' equipped':owned?' unlocked':' locked'}`;
    badge.textContent=equipped?'EM USO':owned?'LIBERADO':`TORNEIO · FASE ${index+1}`;
    controls.append(badge);
    const button=document.createElement('button');button.className='shop-buy';button.disabled=!owned||equipped;button.textContent=equipped?'EQUIPADO':owned?'EQUIPAR':'BLOQUEADO';
    if(owned&&!equipped)button.addEventListener('click',()=>{equippedPower=id;saveProfile();updateCoinDisplay();renderShop();render()});
    controls.append(button);card.append(icon,details,controls);list.appendChild(card);
  }
}
function openShop(){renderShop();const dialog=document.querySelector('#shop-dialog');if(!dialog.open)dialog.showModal()}
function currentMatchSnapshot(){return{version:1,savedAt:Date.now(),mode,gameOver,reviewNonstandardActions,resultText:gameOver?statusEl.textContent:'',humanSide,multiplayerHostColor,clocks:{...clocks},board:board.map(row=>row.slice()),turn,castlingRights:JSON.parse(JSON.stringify(castlingRights)),enPassantTarget:enPassantTarget?enPassantTarget.slice():null,halfmoveClock,repetitionCounts:{...repetitionCounts},history:history.map(item=>({...item,from:item.from.slice(),to:item.to.slice(),boardBefore:item.boardBefore?{...item.boardBefore,board:item.boardBefore.board.map(row=>row.slice()),rights:JSON.parse(JSON.stringify(item.boardBefore.rights)),ep:item.boardBefore.ep?item.boardBefore.ep.slice():null,repetitions:{...item.boardBefore.repetitions}}:null})),reviewTimeline,pendingReviewAction,captured:{w:captured.w.slice(),b:captured.b.slice()},usedPower:{w:{...usedPower.w},b:{...usedPower.b}},extraTurn,pendingPower,pendingRestorePiece,loveTrainRemaining,loveTrainOwner,loveTrainUsed,localPowers:{...localPowers},tournamentRound,tournamentRewarded,playerNames:{...playerNames},playerCharacters:{...playerCharacters},lastMove:lastMove?{from:lastMove.from.slice(),to:lastMove.to.slice()}:null,equippedPower,tournamentResultWon,tournamentResultPending}}
function saveCurrentMatch(){if(mode==='multiplayer'){if(currentUser&&multiplayerConnection?.open&&!multiplayerApplyingState&&!document.querySelector('#game').hidden)syncMultiplayerSnapshot(currentMatchSnapshot());return}if(!currentUser||document.querySelector('#game').hidden)return;if(gameOver){try{localStorage.removeItem(accountStorageKey('activeMatch'))}catch{}queueSave(accountDatabaseKey('activeMatch'),null,true);queueServerState({activeMatch:null});return}const snapshot=currentMatchSnapshot();try{localStorage.setItem(accountStorageKey('activeMatch'),JSON.stringify(snapshot))}catch{}queueSave(accountDatabaseKey('activeMatch'),snapshot);queueServerState({activeMatch:snapshot})}
function updateMultiplayerRoomInfo(){const info=document.querySelector('#multiplayer-room-info');info.hidden=mode!=='multiplayer';document.querySelector('#multiplayer-room-code').textContent=multiplayerRoomCode||'—';const restartButton=document.querySelector('#multiplayer-restart');restartButton.disabled=!multiplayerConnection?.open||!multiplayerGuestJoined||multiplayerRestartRequested;restartButton.textContent=multiplayerRestartRequested?'REINÍCIO SOLICITADO · AGUARDANDO':multiplayerRemoteRestartRequested?'CONFIRMAR REINÍCIO':'↻  PEDIR REINÍCIO · AMBOS CONFIRMAM';if(multiplayerRestartRequested||multiplayerRemoteRestartRequested){updateMultiplayerRestartStatus();return}document.querySelector('#multiplayer-room-status').textContent=!multiplayerGuestJoined?'Aguardando o jogador 2 entrar':canPlayTurn()?'Sua vez de jogar':'Aguardando '+sideDisplayName(turn)+' jogar'}
function closeMultiplayerPeer(){if(multiplayerRestartTimer){clearTimeout(multiplayerRestartTimer);multiplayerRestartTimer=null}const connection=multiplayerConnection,peer=multiplayerPeer;multiplayerConnection=null;multiplayerPeer=null;if(connection)connection.close();if(peer)peer.destroy()}
function makeRoomCode(){const alphabet='23456789ABCDEFGHJKLMNPQRSTUVWXYZ';const bytes=crypto.getRandomValues(new Uint8Array(6));return Array.from(bytes,value=>alphabet[value%alphabet.length]).join('')}
function openMultiplayerPeer(id){return new Promise((resolve,reject)=>{if(!window.Peer){reject(new Error('A biblioteca de conexão não carregou. Atualize a página e tente novamente.'));return}const peer=id?new Peer(id,{debug:1}):new Peer({debug:1});multiplayerPeer=peer;let settled=false;const timeout=setTimeout(()=>{if(!settled){settled=true;peer.destroy();reject(new Error('A conexão com o serviço de salas expirou. Confira sua internet e tente novamente.'))}},15000);peer.on('open',()=>{if(settled)return;settled=true;clearTimeout(timeout);resolve(peer)});peer.on('error',error=>{if(!settled){settled=true;clearTimeout(timeout);peer.destroy();reject(error)}else if(mode==='multiplayer'){const status=document.querySelector('#multiplayer-room-status');if(status)status.textContent='Conexão interrompida · reconecte à sala'}})})}
