async function createMultiplayerRoom(){if(!currentUser)throw new Error('Entre na sua conta antes de criar uma sala.');closeMultiplayerPeer();multiplayerRoomCode=null;multiplayerSeat='w';multiplayerHostColor=randomSide();multiplayerColor=multiplayerHostColor;multiplayerRevision=0;multiplayerReceivedRevision=0;multiplayerGuestJoined=false;multiplayerRestartRequested=false;multiplayerRemoteRestartRequested=false;playerNames={};playerCharacters={};playerNames[multiplayerHostColor]=currentUser.username;playerNames[otherSide(multiplayerHostColor)]='Aguardando jogador 2';playerCharacters[multiplayerHostColor]=document.querySelector('#player-one-character').value;playerCharacters[otherSide(multiplayerHostColor)]=document.querySelector('#player-two-character').value;setMode('multiplayer');document.querySelector('#game-menu').hidden=true;document.querySelector('#game').hidden=false;startClock();let peer,error;for(let attempt=0;attempt<5;attempt++){try{peer=await openMultiplayerPeer(makeRoomCode());break}catch(caught){error=caught;if(caught.type!=='unavailable-id')throw caught}}if(!peer)throw error||new Error('Não foi possível reservar um código de sala.');multiplayerRoomCode=peer.id;peer.on('connection',connection=>{if(multiplayerGuestJoined||multiplayerConnection){connection.close();return}bindMultiplayerConnection(connection);connection.on('open',()=>{const status=document.querySelector('#multiplayer-room-status');if(status)status.textContent='Jogador conectado · preparando partida'})});updateMultiplayerRoomInfo();document.querySelector('#multiplayer-dialog').close();render()}
async function joinMultiplayerRoom(code){if(!currentUser)throw new Error('Entre na sua conta antes de entrar em uma sala.');if(!/^[A-Z0-9]{6}$/.test(code))throw new Error('O código precisa ter seis letras ou números.');closeMultiplayerPeer();multiplayerRoomCode=code;multiplayerSeat='b';multiplayerColor=null;multiplayerRevision=0;multiplayerReceivedRevision=0;multiplayerGuestJoined=false;multiplayerRestartRequested=false;multiplayerRemoteRestartRequested=false;playerNames={w:'Jogador 1',b:currentUser.username};playerCharacters.b=document.querySelector('#player-two-character').value;const peer=await openMultiplayerPeer();const connection=peer.connect(code,{reliable:true,serialization:'json'});bindMultiplayerConnection(connection);await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{multiplayerJoinResolve=null;multiplayerJoinReject=null;reject(new Error('Não foi possível entrar. Confira o código e se a sala ainda está aberta.'))},20000);multiplayerJoinResolve=()=>{clearTimeout(timeout);resolve()};multiplayerJoinReject=error=>{clearTimeout(timeout);reject(error)};connection.on('open',()=>connection.send({type:'join',username:currentUser.username,character:playerCharacters.b}))});updateMultiplayerRoomInfo();document.querySelector('#multiplayer-dialog').close()}

function restoreSavedMatch(saved){if(!saved||saved.version!==1||!['bot','local','multiplayer','tournament'].includes(saved.mode)||!Array.isArray(saved.board)||saved.board.length!==8||saved.board.some(row=>!Array.isArray(row)||row.length!==8)||!['w','b'].includes(saved.turn))return false;playerNames={w:saved.playerNames?.w||'Jogador 1',b:saved.playerNames?.b||'Jogador 2'};playerCharacters={w:characterPhotos[saved.playerCharacters?.w]?saved.playerCharacters.w:'jotaro',b:characterPhotos[saved.playerCharacters?.b]?saved.playerCharacters.b:'jolyne'};setMode(saved.mode);clocks={w:saved.clocks?.w==null?CLOCK_START_MS:Math.max(0,Number(saved.clocks.w)||0),b:saved.clocks?.b==null?CLOCK_START_MS:Math.max(0,Number(saved.clocks.b)||0)};humanSide=saved.humanSide==='b'?'b':'w';if(saved.mode==='multiplayer'){multiplayerHostColor=saved.multiplayerHostColor==='b'?'b':'w';multiplayerColor=multiplayerSeat==='b'?otherSide(multiplayerHostColor):multiplayerHostColor}board=saved.board.map(row=>row.slice());turn=saved.turn;castlingRights=saved.castlingRights||{w:{k:true,q:true},b:{k:true,q:true}};enPassantTarget=saved.enPassantTarget||null;halfmoveClock=Number(saved.halfmoveClock)||0;repetitionCounts=saved.repetitionCounts||{};history=Array.isArray(saved.history)?saved.history:[];reviewTimeline=Array.isArray(saved.reviewTimeline)?saved.reviewTimeline:history.map(item=>({kind:'move',...item}));pendingReviewAction=null;lastReviewRecordedMove=history.at(-1)||null;captured=saved.captured||{w:[],b:[]};usedPower=saved.usedPower||{w:{},b:{}};extraTurn=!!saved.extraTurn;pendingPower=saved.pendingPower||null;pendingRestorePiece=saved.pendingRestorePiece||null;loveTrainRemaining=Number(saved.loveTrainRemaining)||0;loveTrainOwner=saved.loveTrainOwner||null;loveTrainUsed=!!saved.loveTrainUsed;localPowers=saved.localPowers||{w:null,b:null};tournamentRound=Math.min(tournamentOpponents.length-1,Math.max(0,Number(saved.tournamentRound)||0));tournamentRewarded=!!saved.tournamentRewarded;tournamentResultWon=!!saved.tournamentResultWon;tournamentResultPending=!!saved.tournamentResultPending;equippedPower=ownedPowers.includes(saved.equippedPower)?saved.equippedPower:equippedPower;gameOver=!!saved.gameOver;reviewNonstandardActions=!!saved.reviewNonstandardActions;selected=null;legal=[];lastMove=saved.lastMove|| (history.length?{from:history[history.length-1].from,to:history[history.length-1].to}:null);document.querySelector('#game-menu').hidden=true;document.querySelector('#game').hidden=false;startClock();if(tournamentResultPending){const next=document.querySelector('#tournament-next');next.hidden=false;next.textContent=tournamentResultWon?(tournamentRound===tournamentOpponents.length-1?'CONCLUIR TORNEIO':'AVANÇAR NO TORNEIO'):'TENTAR ESTA FASE DE NOVO'}updateOpponent();render();renderLog();renderCaptures();if(isSinglePlayerMode()&&turn===otherSide(humanSide))scheduleBot();return true}
async function initializeSavedGame(accountState={}){
  document.querySelectorAll('[data-start-mode]').forEach(button=>button.disabled=true);
  const readLocal=key=>{try{return JSON.parse(localStorage.getItem(key)||'null')}catch{return null}};
  const oldProfile=readLocal('jojoChessProfile'),scopedProfile=readLocal(accountStorageKey('profile'));
  const oldMatch=readLocal('jojoChessActiveMatch'),scopedMatch=readLocal(accountStorageKey('activeMatch'));
  let oldDbProfile=null,scopedDbProfile=null,oldDbMatch=null,scopedDbMatch=null;
  [oldDbProfile,scopedDbProfile,oldDbMatch,scopedDbMatch]=await Promise.all([
    readSavedValue('profile').catch(()=>null),readSavedValue(accountDatabaseKey('profile')).catch(()=>null),
    readSavedValue('activeMatch').catch(()=>null),readSavedValue(accountDatabaseKey('activeMatch')).catch(()=>null)
  ]);
  const latest=values=>values.filter(value=>value&&typeof value==='object').reduce((best,value)=>!best||(value.savedAt||0)>=(best.savedAt||0)?value:best,null);
  const profile=latest([oldProfile,oldDbProfile,scopedProfile,scopedDbProfile,accountState.profile]);
  const match=latest([oldMatch,oldDbMatch,scopedMatch,scopedDbMatch,accountState.activeMatch]);
  if(profile){try{localStorage.setItem(accountStorageKey('profile'),JSON.stringify(profile))}catch{}}
  if(match){try{localStorage.setItem(accountStorageKey('activeMatch'),JSON.stringify(match))}catch{}queueSave(accountDatabaseKey('activeMatch'),match)}
  try{localStorage.removeItem('jojoChessProfile');localStorage.removeItem('jojoChessActiveMatch')}catch{}
  queueSave('profile',null,true);queueSave('activeMatch',null,true);
  loadProfile();document.querySelector('#player-one-character').value=profileCharacter;saveProfile();updateCoinDisplay();renderShop();
  if(!match||match.gameOver||!restoreSavedMatch(match)){resetRound();if(match?.gameOver)saveCurrentMatch()}else saveCurrentMatch();
  document.querySelectorAll('[data-start-mode]').forEach(button=>button.disabled=false);
}
function resetRoundCore(){botTurnToken++;stopPowerSounds();loveTrainRemaining=0;loveTrainOwner=null;loveTrainUsed=false;localPowers={w:null,b:null};if(isTwoPlayerMode()){const pool=powerOrder.slice();for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}localPowers={w:pool[0],b:pool[1]}}board=initial();turn='w';castlingRights={w:{k:true,q:true},b:{k:true,q:true}};enPassantTarget=null;halfmoveClock=0;repetitionCounts={};repetitionCounts[positionKey()]=1;promotionPending=null;pendingRestorePiece=null;selected=null;legal=[];lastMove=null;history=[];reviewTimeline=[];pendingReviewAction=null;lastReviewRecordedMove=null;captured={w:[],b:[]};usedPower={w:{},b:{}};extraTurn=false;gameOver=false;botThinking=false;pendingPower=null;reviewNonstandardActions=false;if(document.querySelector('#result-overlay').open)document.querySelector('#result-overlay').close();document.querySelector('#tournament-next').hidden=true;document.querySelector('#claim-draw').hidden=true;boardEl.classList.remove('thinking');render();renderLog();renderCaptures();renderBracket()}
