function updateOpponent(){const op=mode==='tournament'?tournamentOpponents[tournamentRound]:null,profileFor=color=>characterPhotos[playerCharacters[color]]||characterPhotos[color==='w'?'jotaro':'jolyne'],whiteProfile=profileFor('w'),blackProfile=profileFor('b'),captionFor=color=>{if(isTwoPlayerMode())return profileFor(color).name.toLocaleUpperCase()+' · PEÇAS '+(color==='w'?'BRANCAS':'PRETAS')+' · PODER ALEATÓRIO: '+(powerInfo[localPowers[color]]?.title||'—');if(color===humanSide)return'VOCÊ · PEÇAS '+(color==='w'?'BRANCAS':'PRETAS');return mode==='tournament'?op.caption+' · PEÇAS '+(color==='w'?'BRANCAS':'PRETAS')+' · '+(isTournamentOpponentPowered()?'PODER: '+(op.powerName||powerInfo[op.power].title):'PODER INATIVO'):'DIO BRANDO · BOT · PEÇAS '+(color==='w'?'BRANCAS':'PRETAS')};document.querySelector('#opponent-name').textContent=sideDisplayName('b');document.querySelector('#current-player-name').textContent=sideDisplayName('w');document.querySelector('#captures-title').textContent='TROFÉUS DE '+sideDisplayName('w').toLocaleUpperCase();document.querySelector('#white-legend-name').textContent=sideDisplayName('w');document.querySelector('#black-legend-name').textContent=sideDisplayName('b');document.querySelector('#opponent-avatar').innerHTML='<img class="character-photo" src="assets/fotos/'+encodeURIComponent(blackProfile.file).replaceAll('%2F','/')+'" alt="Foto de '+blackProfile.name+'">';document.querySelector('#player-avatar').innerHTML='<img class="character-photo" src="assets/fotos/'+encodeURIComponent(whiteProfile.file).replaceAll('%2F','/')+'" alt="Foto de '+whiteProfile.name+'">';document.querySelector('#opponent-caption').textContent=captionFor('b');document.querySelector('#current-caption').textContent=captionFor('w');renderBracket()}
const tutorialSteps=[
  {title:'A meta é dar xeque-mate',intro:'Proteja seu rei e encurrale o rei adversário. Você vence quando ele está ameaçado e não existe nenhum lance legal para escapar.',items:[['Xeque','O rei está sob ataque. O jogo avisa; você precisa protegê-lo no próximo lance.'],['Xeque-mate','O rei está sob ataque e não consegue escapar. A partida termina.'],['Empate','Também pode acontecer se nenhum lado puder vencer ou se uma regra de empate for alcançada.']]},
  {title:'Conheça o tabuleiro',intro:'O tabuleiro tem 8 linhas e 8 colunas. Cada lado controla 16 peças, e as peças brancas começam.',items:[['Casas','As letras a–h identificam as colunas; os números 1–8 identificam as linhas.'],['Seu lado','No modo contra o bot, você pode receber as peças brancas ou pretas. O indicador dourado mostra de quem é a vez.'],['Rei primeiro','O rei é a peça que você precisa proteger. Não é permitido fazer um lance que o deixe em xeque.']]},
  {title:'Como as peças se movem',intro:'Clique numa peça sua para ver as casas permitidas e depois clique no destino. As casas destacadas indicam os lances possíveis.',items:[['♔ Rei','Uma casa em qualquer direção.'],['♕ Dama','Quantas casas quiser em linha reta ou diagonal.'],['♖ Torre · ♗ Bispo','Torre: em linha reta. Bispo: na diagonal.'],['♘ Cavalo · ♙ Peão','Cavalo: em “L” e pode saltar peças. Peão: avança para frente e captura na diagonal.']]},
  {title:'Turnos e relógio',intro:'Os jogadores alternam os lances. O relógio de 10 minutos começa na vez de cada lado e pausa quando o lance termina.',items:[['Fazer um lance','Selecione sua peça e depois uma casa marcada. Para capturar, escolha uma casa marcada com um círculo.'],['Relógio zerado','Se o tempo de um lado acabar, a partida termina.'],['Regras especiais','Peões podem ser promovidos ao chegar ao fim do tabuleiro. Roque e en passant também estão disponíveis; as regras ficam abaixo do tabuleiro.']]},
  {title:'Poderes dos Stands',intro:'Poderes são opcionais e variam conforme o modo. Leia o cartão ao lado do tabuleiro antes de ativar um poder.',items:[['Ativar','Clique em ATIVAR PODER. Alguns poderes pedem que você escolha uma peça ou casa depois.'],['Recarga','Poderes usados precisam de turnos para recarregar. O cartão mostra quantos faltam.'],['Efeito','Parada do Tempo dá um lance extra; outros poderes podem transformar, remover, restaurar ou desfazer peças.']]},
  {title:'Escolha como jogar',intro:'Você pode jogar sozinho, no mesmo dispositivo ou online.',items:[['Contra o bot','Partida rápida contra DIO. Você controla um lado e o bot joga pelo outro.'],['1 vs 1 local','Duas pessoas usam o mesmo dispositivo e alternam os lances.'],['Torneio JoJo','Enfrente seis rivais. Vitórias liberam poderes para usar contra o bot.'],['Multiplayer','Crie uma sala e compartilhe o código com a outra pessoa.']]},
  {title:'Leia a tela e comece',intro:'As informações da partida ajudam você a acompanhar o que está acontecendo.',items:[['Lances da partida','Veja todos os lances, quem moveu e as casas de origem e destino.'],['Peças capturadas','Confira as peças retiradas do tabuleiro.'],['Nova partida e menu','Reinicie a partida ou volte ao menu pelos botões ao lado. Você pode abrir este tutorial novamente quando quiser.']]}
];
