function undoLastMove(){const last=history.pop();if(!last)return false;board=last.boardBefore.board;castlingRights=last.boardBefore.rights;enPassantTarget=last.boardBefore.ep;halfmoveClock=last.boardBefore.halfmove;repetitionCounts=last.boardBefore.repetitions;if(last.captured)captured[last.piece[0]].pop();lastMove=history.length?{from:history[history.length-1].from,to:history[history.length-1].to}:null;selected=null;legal=[];pendingPower=null;render();renderLog();renderCaptures();saveCurrentMatch();return true}
powerButton.addEventListener('click',()=>{const power=isTwoPlayerMode()?localPowers[turn]:isSinglePlayerMode()&&turn===humanSide?equippedPower:null;if(!power)return;if((usedPower[turn][power]||0)>0||gameOver||!canPlayTurn())return;if(power==='time'){queueReviewPower('time',turn,'Parada do Tempo: ganhou um lance extra.');showPowerEffect('time',turn);usedPower[turn][power]=3;extraTurn=true;recordImmediateReviewPower();statusEl.textContent=`O tempo parou! ${sideDisplayName(turn)} ganha mais um lance.`}else if(power==='hamon'||power==='killer'){usedPower[turn][power]=3;pendingPower=power;statusEl.textContent=power==='hamon'?'Onda Hamon: escolha um peão inimigo no tabuleiro.':'Killer Queen: escolha uma peça inimiga para explodir.'}else if(power==='arrow'){usedPower[turn][power]=3;if(selected&&type(board[selected[0]][selected[1]])==='p'){queueReviewPower('arrow',turn,`Flecha do Stand: promoveu o peão em ${squareName(selected)} a dama.`,selected,selected);showPowerEffect('arrow',turn);board[selected[0]][selected[1]]=turn+'q';halfmoveClock=0;selected=null;legal=[];completeAction();return}pendingPower='arrow';statusEl.textContent='Flecha do Stand: escolha um peão seu no tabuleiro.'}else if(power==='diamond'){const stash=captured[turn==='w'?'b':'w'];pendingRestorePiece=stash[stash.length-1];if(!pendingRestorePiece){statusEl.textContent='Ainda não há peça capturada para restaurar.';return}usedPower[turn][power]=3;pendingPower='diamond';statusEl.textContent=`Crazy Diamond: escolha uma casa vazia para restaurar ${names[type(pendingRestorePiece)]}.`}else{const last=history[history.length-1];if(!last||last.piece[0]===turn||!last.boardBefore){statusEl.textContent='Apagar o Tempo só funciona após um movimento inimigo.';return}usedPower[turn][power]=3;queueReviewPower('crimson',turn,'Apagar o Tempo: desfez o último lance adversário.');showPowerEffect('crimson',turn);undoLastMove();recordImmediateReviewPower();return}render();saveCurrentMatch()});
