document.querySelector('#tournament-next').addEventListener('click',()=>{const won=tournamentResultWon;tournamentResultWon=false;tournamentResultPending=false;if(won){if(tournamentRound===tournamentOpponents.length-1){tournamentRound=0;tournamentRewarded=false;prepareSinglePlayerSides('tournament');resetRound();updateOpponent();statusEl.textContent='Torneio concluído! Confira sua recompensa na loja.';saveCurrentMatch();return}tournamentRound++}prepareSinglePlayerSides('tournament');resetRound();updateOpponent();if(turn===otherSide(humanSide))scheduleBot();saveCurrentMatch()});
document.querySelector('#reset').addEventListener('click',()=>{tournamentResultWon=false;tournamentResultPending=false;if(mode==='tournament')tournamentRound=0;if(mode==='local'){readPlayerNames();randomizeLocalSides()}else prepareSinglePlayerSides(mode);resetRound();updateOpponent();if(isSinglePlayerMode()&&turn===otherSide(humanSide))scheduleBot();saveCurrentMatch()});
document.querySelectorAll('.promotion-options button').forEach(button=>button.addEventListener('click',()=>{if(!promotionPending)return;const {from,to}=promotionPending;promotionPending=null;const dialog=document.querySelector('#promotion-dialog');if(dialog.close)dialog.close();else dialog.removeAttribute('open');makeMove(from,to,button.dataset.piece)}));
document.querySelector('#claim-draw').addEventListener('click',()=>{const key=positionKey();if(repetitionCounts[key]>=3||halfmoveClock>=100){gameOver=true;statusEl.textContent=repetitionCounts[key]>=3?'EMPATE REIVINDICADO POR REPETIÇÃO':'EMPATE REIVINDICADO PELA REGRA DOS 50 LANCES';document.querySelector('#claim-draw').hidden=true;if(mode==='tournament'){document.querySelector('#tournament-next').hidden=false;document.querySelector('#tournament-next').textContent='TENTAR ESTA FASE DE NOVO'}render();showGameResult(statusEl.textContent)}});
document.querySelector('#shop-dialog').addEventListener('click',event=>{if(event.target.id==='shop-dialog')event.target.close()});

window.addEventListener('pagehide',()=>{stopPowerSounds();closeMultiplayerPeer()});
